    'Nh': 113, 'Fl': 114, 'Mc': 115, 'Lv': 116, 'Ts': 117, 'Og': 118
}

def get_element_z(isotope_name):
    match = re.search(r'(\d+)$', isotope_name)
    if match:
        prefix = isotope_name[:match.start()]
        elem_match = re.match(r'^[A-Za-z]+', prefix)
        if elem_match:
            element_str = elem_match.group(0).lower()
            if element_str in ELEMENT_Z:
                return ELEMENT_Z[element_str]
    return None

def parse_isotope_for_sort(isotope_name):
    z = get_element_z(isotope_name)
    if z is None:
        z = 0
    match = re.search(r'(\d+)$', isotope_name)
    if match:
        a = int(match.group(1))
    else:
        a = 0
    return z, a

def sort_isotopes_for_output(isotopes_list):
    def compare_items(a, b):
        # Safely get isotope name
        iso_a = a.get("isotope", "")
        iso_b = b.get("isotope", "")
        z_a, a_val_a = parse_isotope_for_sort(iso_a)
        z_b, a_val_b = parse_isotope_for_sort(iso_b)
        if z_a != z_b:
            if z_a > z_b:
                return -1
            elif z_a < z_b:
                return 1
        if a_val_a != a_val_b:
            if a_val_a > a_val_b:
                return -1
            elif a_val_a < a_val_b:
                return 1
        if iso_a > iso_b:
            return -1
        elif iso_a < iso_b:
            return 1
        return 0
    return sorted(isotopes_list, key=functools.cmp_to_key(compare_items))

def find_xs_files(base_dir):
    files = []
    if not os.path.exists(base_dir):
        return files
    for root, dirs, filenames in os.walk(base_dir):
        for filename in filenames:
            if filename.endswith('.xs'):
                full_path = os.path.join(root, filename)
                rel_path = os.path.relpath(full_path, base_dir)
                parts = rel_path.split(os.sep)
                depth = len(parts) - 1
                files.append({
                    'full_path': full_path,
                    'rel_path': rel_path,
                    'depth': depth
                })
    return files

def sort_files(files):
    files.sort(key=lambda x: x['full_path'], reverse=True)
    files.sort(key=lambda x: -x['depth'])
    return files

def parse_file(filepath):
    try:
        with open(filepath, 'r') as f:
            content = f.read()
    except Exception:
        return None
    lines = content.splitlines()
    isotope_records = []
    current_isotope = None
    current_data = []
    for line in lines:
        line = line.rstrip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('ISOTOPE:'):
            if current_isotope is not None:
                isotope_records.append({'name': current_isotope, 'data': current_data})
            current_isotope = line.split(':', 1)[1].strip()
            current_data = []
        elif line.startswith('ENERGY:'):
            parts = line.split()
            energy_val = sigma_t = sigma_a = sigma_s = None
            for part in parts:
                if part.startswith('ENERGY:'):
                    try:
                        energy_val = float(part.split(':')[1].strip())
                    except:
                        energy_val = None
                elif part.startswith('SIGMA_T:'):
                    try:
                        sigma_t = float(part.split(':')[1].strip())
                    except:
                        sigma_t = None
                elif part.startswith('SIGMA_A:'):
                    try:
                        sigma_a = float(part.split(':')[1].strip())
                    except:
                        sigma_a = None
                elif part.startswith('SIGMA_S:'):
                    try:
                        sigma_s = float(part.split(':')[1].strip())
                    except:
                        sigma_s = None
            if energy_val is not None:
                current_data.append({'energy': energy_val, 'sigma_t': sigma_t, 'sigma_a': sigma_a, 'sigma_s': sigma_s})
    if current_isotope is not None:
        isotope_records.append({'name': current_isotope, 'data': current_data})
    return isotope_records

def normalize_isotope_name(name):
    return name.lower().replace(' ', '').replace('-', '')

def has_valid_isotope_name(name):
    return bool(re.search(r'\d', name))

def load_atomic_densities(filepath):
    densities = {}
    if not os.path.exists(filepath):
        return None
    try:
        with open(filepath, 'r') as f:
            for line in f:
                line = line.rstrip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split(':')
                if len(parts) >= 3:
                    isotope_name = parts[0]
                    density = parts[1]
                    mass = parts[2]
                    densities[isotope_name] = {'density': density, 'mass': mass}
    except Exception:
        return None
    return densities

def get_density_info(densities_dict, isotope_name):
    if isotope_name in densities_dict:
        return densities_dict[isotope_name]
    for key in densities_dict:
        if key.lower() == isotope_name.lower():
            return densities_dict[key]
    norm_name = normalize_isotope_name(isotope_name)
    for key in densities_dict:
        if normalize_isotope_name(key) == norm_name:
            return densities_dict[key]
    return None

def main():
    base_dir = '/app/data/cross_sections'
    xs_files = find_xs_files(base_dir)
    xs_files = sort_files(xs_files)

    atomic_densities_path = '/app/data/atomic_densities.txt'
    densities_file = load_atomic_densities(atomic_densities_path)

    seen_isotopes = {}
    isotopes_output = []
    total_files = len(xs_files)
    file_all_valid = [True] * total_files

    for idx, fs in enumerate(xs_files):
        filepath = fs['full_path']
        rel_path = fs['rel_path']

        parsed = parse_file(filepath)
        if parsed is None:
            file_all_valid[idx] = False
            continue

        for iso_rec in parsed:
            isotope_name = iso_rec['name']
            data = iso_rec['data']

            validation_errors = []
            for entry in data:
                for key in ['energy', 'sigma_t', 'sigma_a', 'sigma_s']:
                    val = entry[key]
                    if math.isnan(val) or math.isinf(val):
                        validation_errors.append("invalid_value")
            for entry in data:
                if entry['sigma_t'] < 0 or entry['sigma_a'] < 0 or entry['sigma_s'] < 0:
                    validation_errors.append("negative_cross_section")
            for entry in data:
                if abs(entry['sigma_t'] - (entry['sigma_a'] + entry['sigma_s'])) > 0.001:
                    validation_errors.append("cross_section_mismatch")
            if not data:
                validation_errors.append("invalid_energy_ordering")
            else:
                if data[0]['energy'] <= 0:
                    validation_errors.append("invalid_energy_ordering")
                prev = None
                for entry in data:
                    if prev is not None:
                        if entry['energy'] <= prev:
                            validation_errors.append("invalid_energy_ordering")
                    prev = entry['energy']
            if not has_valid_isotope_name(isotope_name):
                validation_errors.append("invalid_isotope_name")

            norm_name = normalize_isotope_name(isotope_name)
            is_duplicate = norm_name in seen_isotopes

            status = "valid"
            if "cross_section_mismatch" in validation_errors:
                status = "cross_section_mismatch"
            elif "invalid_energy_ordering" in validation_errors:
                status = "invalid_energy_ordering"
            elif "negative_cross_section" in validation_errors:
                status = "negative_cross_section"
            elif "invalid_isotope_name" in validation_errors:
                status = "invalid_isotope_name"
            elif is_duplicate:
                status = "duplicate_isotope"
            else:
                candidates = []
                for entry in data:
                    dist = abs(entry['energy'] - 0.025)
                    if dist <= 0.1:
                        candidates.append((entry['energy'], entry['sigma_t'], dist))
                if not candidates:
                    status = "insufficient_data"
                else:
                    candidates.sort(key=lambda x: (x[2], -x[0]))
                    best = candidates[0]
                    thermal_xs_val = best[1]
                    density_info = get_density_info(densities_file, isotope_name)
                    if density_info is None:
                        status = "missing_density_data"
                    else:
                        status = "valid"

            if status != "valid":
                file_all_valid[idx] = False

            if norm_name not in seen_isotopes:
                seen_isotopes[norm_name] = rel_path

            entry = {
                "isotope": isotope_name,
                "source_file": rel_path,
                "status": status,
                "validation_errors": sorted(validation_errors)
            }
            if status == "valid":
                density_info = get_density_info(densities_file, isotope_name)
                density_g_cm3 = float(density_info['density'])
                atomic_mass = float(density_info['mass'])
                N_unrounded = (density_g_cm3 / atomic_mass) * 6.02214076e23
                candidates = []
                for entry in data:
                    dist = abs(entry['energy'] - 0.025)
                    if dist <= 0.1:
                        candidates.append((entry['energy'], entry['sigma_t'], dist))
                candidates.sort(key=lambda x: (x[2], -x[0]))
                thermal_xs_barns = candidates[0][1]
                sigma_cm2 = thermal_xs_barns * 1e-24
                macroscopic_xs_unrounded = N_unrounded * sigma_cm2
                macroscopic_xs_rounded = round(macroscopic_xs_unrounded, 6)
                reaction_rate = 1e14 * macroscopic_xs_rounded
                reaction_rate_rounded = round(reaction_rate, 6)
                entry["atomic_density_atoms_cm3"] = round(N_unrounded, 6)
                entry["macroscopic_cross_section_cm_minus1"] = macroscopic_xs_rounded
                entry["reaction_rate_reactions_cm3_s"] = reaction_rate_rounded
                entry["thermal_xs_barns"] = round(thermal_xs_barns, 6)
            else:
                entry["atomic_density_atoms_cm3"] = None
                entry["macroscopic_cross_section_cm_minus1"] = None
                entry["reaction_rate_reactions_cm3_s"] = None
                entry["thermal_xs_barns"] = None
            isotopes_output.append(entry)

    valid_files = sum(1 for f in file_all_valid if f)
    invalid_files = total_files - valid_files
    total_isotopes = len(isotopes_output)
    valid_isotopes = sum(1 for iso in isotopes_output if iso.get("status") == "valid")
    invalid_isotopes = total_isotopes - valid_isotopes

    result = {
        "total_files": total_files,
        "valid_files": valid_files,
        "invalid_files": invalid_files,
        "total_isotopes": total_isotopes,
        "valid_isotopes": valid_isotopes,
        "invalid_isotopes": invalid_isotopes,
        "isotopes": sort_isotopes_for_output(isotopes_output)
    }

    tmp_path = "/app/cross_section_report.json.tmp"
    with open(tmp_path, 'w') as f:
        json.dump(result, f)
    os.rename(tmp_path, "/app/cross_section_report.json")

if __name__ == "__main__":
    main()
